bu_func &lt;- function(n_items, rep = 1) {
  pmap(expand_grid(n_items = n_items, rep = rep), 
          \(n_items, rep) {

            bu_long |&gt;
              filter(unique_trial %in% sample(unique_trial, n_items)) |&gt;
              select(sscore, score) |&gt;
              drop_na() |&gt;
              summarize(n_items = n_items,
                        rep = rep,
                        cor = cor(sscore, score) |&gt; abs())
          }) |&gt;
    list_rbind()
}

bu_cors &lt;- bu_func(1:7, 1:20)
